  "recovered_c": "uint64_t fn_10(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len == 0) {\n    return 1;\n  }\n  uint uVar2 = 0;\n  uint uVar3 = 1;\n  for (size_t i = 0; i < len; i++) {\n    uint8_t bVar1 = in[i];\n    uVar3 = (uVar3 + bVar1) % 0xffef;\n    uVar2 = (uVar2 + uVar3) % 0xffef;\n  }\n  out[0] = (uVar2 >> 8) & 0xff;\n  out[1] = uVar2 & 0xff;\n  return uVar2 << 0x10 | uVar3;\n}"
